#!/bin/bash
sed -i 's/<div className="hidden md:flex flex-col items-end gap-1 shrink-0">/<div className="flex items-center gap-2 ml-1 sm:ml-2 shrink-0"><button onClick={() => setIsProMode(!isProMode)} className={`relative inline-flex h-5 sm:h-6 w-9 sm:w-11 shrink-0 cursor-pointer items-center justify-center rounded-full transition-colors ${isProMode ? "bg-amber-500" : isLightMode ? "bg-gray-300" : "bg-white\/20"}`}><span className={`inline-block h-3 sm:h-4 w-3 sm:w-4 transform rounded-full bg-white transition-transform ${isProMode ? "translate-x-2 sm:translate-x-3" : "-translate-x-2 sm:-translate-x-3"}`} \/><\/button><span className={`text-[9px] sm:text-[10px] font-bold uppercase tracking-widest ${isProMode ? "text-amber-500" : isLightMode ? "text-gray-400" : "text-white\/40"}`}>PRO<\/span><\/div>\n          {false \&\& <div className="hidden md:flex flex-col items-end gap-1 shrink-0">/g' src/components/Header.tsx
sed -i 's/ИИ-Подбор/ИИ-Подбор/g' src/components/Header.tsx
sed -i 's/<\/p>\n          <\/div>/<\/p>\n          <\/div>}/g' src/components/Header.tsx
